func (q *Queries) ListAdminUsers(ctx context.Context, arg ListAdminUsersParams) ([]ListAdminUsersRow, error) {
	rows, err := q.db.Query(ctx, listAdminUsers,
		arg.LastActivityFrom,
		arg.LastActivityTo,
		arg.AfterUserID,
		arg.SortField,
		arg.SortDirection,
		arg.AfterSortTime,
		arg.AfterSortText,
		arg.PageSize,
		arg.SampledAt,
		arg.UserID,
		arg.Statuses,
		arg.UsernamePrefix,
		arg.TagIds,
		arg.CreatedFrom,
		arg.CreatedTo,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListAdminUsersRow{}
	for rows.Next() {
		var i ListAdminUsersRow
		if err := rows.Scan(
			&i.UserID,
			&i.Status,
			&i.Username,
			&i.CurrentUsernameKey,
			&i.UsernameChangedAt,
			&i.AccountVersion,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.LastActivityAt,
			&i.UsernameSortKey,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

